text:
{
 "contract_type": "msa",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Kestrel Logistics Corp."],
   "quote": "by and between Northwind Labs, Inc., a Delaware corporation (\"Northwind\"), and Kestrel Logistics Corp. (\"Kestrel\")"
  },
  "counterparty": {
   "value": "Kestrel Logistics Corp.",
   "quote": "and Kestrel Logistics Corp. (\"Kestrel\")"
  },
  "effective_date": {
   "value": "2025-01-01",
   "quote": "entered into as of 1st day of January, 2025 (the \"Effective Date\")"
  },
  "term_months": {
   "value": 24,
   "quote": "The initial term of this Agreement is two years (the \"Initial Term\")."
  },
  "auto_renewal": {
   "value": true,
   "quote": "Thereafter, this Agreement shall automatically renew for successive one (1) year periods unless either Party provides written notice of non-renewal"
  },
  "renewal_notice_days": {
   "value": 90,
   "quote": "unless either Party provides written notice of non-renewal at least ninety (90) days prior to the end of the then-current term"
  },
  "governing_law": {
   "value": "Florida",
   "quote": "this Agreement is construed under the laws of the State of Florida"
  },
  "liability_cap": {
   "value": "fees_12m",
   "quote": "IN NO EVENT SHALL EITHER PARTY'S AGGREGATE LIABILITY ARISING OUT OF THIS AGREEMENT EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM."
  },
  "payment_terms_days": {
   "value": 15,
   "quote": "Northwind shall pay all undisputed invoices within fifteen (15) days of receipt."
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": null,
   "quote": null
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Samuel Okafor",
   "email": "samuel.okafor@kestrel.example",
   "title": "General Counsel",
   "party": "Kestrel Logistics Corp."
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "short_payment_window",
   "severity": "medium",
   "message": "Northwind must pay undisputed invoices within 15 days of receipt, which is a tight window and risks late-payment breaches.",
   "quote": "Northwind shall pay all undisputed invoices within fifteen (15) days of receipt."
  },
  {
   "id": "auto_renewal_notice_window",
   "severity": "medium",
   "message": "The agreement auto-renews for one-year periods unless notice is given 90 days before term end. The initial term ended 2026-12-31, so the non-renewal deadline is about 2026-10-02 and has likely already passed, which would lock in renewal through 2027.",
   "quote": "unless either Party provides written notice of non-renewal at least ninety (90) days prior to the end of the then-current term"
  },
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "The contract has no termination clause, so Northwind has no clear right to exit early, including for breach or convenience.",
   "quote": "The initial term of this Agreement is two years (the \"Initial Term\")."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "medium",
   "message": "There is no confidentiality clause, so Northwind's information is not contractually protected.",
   "quote": "Kestrel will provide professional services to Northwind under one or more Statements of Work."
  },
  {
   "id": "florida_exclusive_venue",
   "severity": "low",
   "message": "Disputes must be brought exclusively in Florida courts, which may be inconvenient and costly for Delaware-based Northwind.",
   "quote": "Any dispute shall be resolved exclusively in the courts located in Florida"
  },
  {
   "id": "fees_deferred_to_sow",
   "severity": "low",
   "message": "Fees are not stated in the MSA, so the cap and total cost depend on each SOW and the liability cap amount is undefined until fees exist.",
   "quote": "Fees for the Services are set out in each Statement of Work."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a two-year Master Services Agreement, effective January 1, 2025, under which Kestrel Logistics Corp. provides services to Northwind Labs, Inc. under Statements of Work, with automatic one-year renewals. It is governed by Florida law, caps each party's liability at 12 months of fees, and requires Northwind to pay invoices within 15 days."
}
